content.content:
:root {
  --paper: #fbfaf7;
  --panel: #ffffffee;
  --ink: #1f2328;
  --line: #d9d6cf;
  --accent: #0090ff;
  color-scheme: light;
}

html,
body,
#app {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  overscroll-behavior: none;
  background: var(--paper);
  color: var(--ink);
  font-family: system-ui, sans-serif;
  user-select: none;
  -webkit-user-select: none;
  -webkit-touch-callout: none;
  -webkit-tap-highlight-color: transparent;
  touch-action: none;
}

.board {
  position: fixed;
  inset: 0;
}

.surface {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: crosshair;
}

.surface.panning {
  cursor: grab;
}

.surface.erasing {
  cursor: cell;
}

.toolbar {
  position: fixed;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 6px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--panel);
  box-shadow: 0 2px 8px #0000001a;
}

.group {
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
  display: flex;
  gap: 4px;
}

.tool {
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 8px;
  background: transparent;
  cursor: pointer;
}

.tool[aria-pressed="true"] {
  border-color: var(--accent);
}

.dot {
  display: block;
  border-radius: 50%;
  background: var(--ink);
}

.swatch {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 2px var(--panel);
}

.swatch.secondary {
  outline: 2px dashed var(--line);
  outline-offset: 1px;
}

.pair {
  position: relative;
}

.chip {
  position: absolute;
  width: 16px;
  height: 16px;
  border: 2px solid var(--panel);
  border-radius: 4px;
}

.chip.back {
  right: 4px;
  bottom: 4px;
}

.chip.front {
  left: 4px;
  top: 4px;
}

.error {
  position: fixed;
  left: 16px;
  right: 16px;
  bottom: 16px;
  padding: 12px 16px;
  border: 1px solid #e5484d;
  border-radius: 10px;
  background: #fff5f5;
  color: #8a1c1f;
  user-select: text;
  -webkit-user-select: text;
}

.error p {
  margin: 0 0 8px;
}

.status {
  width: 10px;
  height: 10px;
  margin: 0 4px;
  border-radius: 50%;
  background: #8b8d98;
}

.status[data-connection="Connected"] {
  background: #30a46c;
}

.status[data-connection="Reconnecting"] {
  background: #f76b15;
}

.status[data-connection="Offline"] {
  background: #e5484d;
}
import { PALETTE, PENCIL_SIZES } from "./stroke";
import type { Tool } from "./surface";
import { CONNECTION_LABEL, type Connection } from "./sync";

const DOT_PX = { Small: 4, Medium: 9, Large: 16 } as const;

type ToolbarProps = { tool: Tool; onChange: (tool: Tool) => void; connection: Connection };

export function Toolbar({ tool, onChange, connection }: ToolbarProps) {
  return (
    <div class="toolbar" role="toolbar" aria-label="Drawing tools">
      <fieldset class="group" aria-label="Pencil size">
        {PENCIL_SIZES.map((size) => (
          <button
            key={size}
            type="button"
            aria-pressed={tool.mode === "Pencil" && tool.size === size}
            aria-label={`${size} pencil`}
            class="tool"
            onClick={() => onChange({ ...tool, size, mode: "Pencil" })}
          >
            <span class="dot" style={{ width: DOT_PX[size], height: DOT_PX[size] }} />
          </button>
        ))}
      </fieldset>
      <fieldset class="group" aria-label="Colour">
        {PALETTE.map((colour, index) => (
          <button
            key={colour}
            type="button"
            aria-pressed={tool.primary === index}
            aria-label={`Colour ${index + 1}`}
            title="Tap for primary, right-click or long-press for secondary"
            class={tool.secondary === index ? "tool swatch secondary" : "tool swatch"}
            style={{ background: colour }}
            onClick={() => onChange({ ...tool, primary: index })}
            onContextMenu={(event) => {
              event.preventDefault();
              onChange({ ...tool, secondary: index });
            }}
          />
        ))}
      </fieldset>
      <button
        type="button"
        class="tool"
        aria-pressed={tool.mode === "Pan"}
        aria-label="Pan tool"
        title="Drag with one finger to move the board"
        onClick={() => onChange({ ...tool, mode: tool.mode === "Pan" ? "Pencil" : "Pan" })}
      >
        <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
          <path
            d="M12 2v20M2 12h20M12 2l-3 3M12 2l3 3M12 22l-3-3M12 22l3-3M2 12l3-3M2 12l3 3M22 12l-3-3M22 12l-3 3"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linecap="round"
          />
        </svg>
      </button>
      <button
        type="button"
        class="tool"
        aria-pressed={tool.mode === "Eraser"}
        aria-label="Eraser"
        title="Tap or drag across a stroke to delete it"
        onClick={() => onChange({ ...tool, mode: tool.mode === "Eraser" ? "Pencil" : "Eraser" })}
      >
        <svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
          <path
            d="M16 3l5 5-11 11H5l-3-3L16 3zM9 10l5 5M10 21h11"
            fill="none"
            stroke="currentColor"
            stroke-width="2"
            stroke-linejoin="round"
            stroke-linecap="round"
          />
        </svg>
      </button>
      <button
        type="button"
        class="tool pair"
        aria-label="Swap primary and secondary colour"
        onClick={() => onChange({ ...tool, primary: tool.secondary, secondary: tool.primary })}
      >
        <span class="chip back" style={{ background: PALETTE[tool.secondary] }} />
        <span class="chip front" style={{ background: PALETTE[tool.primary] }} />
      </button>
      <span
        class="status"
        data-connection={connection}
        role="status"
        aria-label={CONNECTION_LABEL[connection]}
        title={CONNECTION_LABEL[connection]}
      />
    </div>
  );
}
import type { StoredObject } from "@stallion/client-store";
import { type Point, type Tile, tileBounds } from "@stallion/geometry";
import type { PencilSize, Stroke } from "@stallion/schema";
import {
  type Camera,
  pan,
  pinch,
  screenToWorld,
  viewBounds,
  wheelFactor,
  worldToScreen,
  zoomAt,
} from "./camera";
import { isVisible } from "./culling";
import { hitsStroke } from "./eraser";
import { createGestures, type Effect, type PointerKind } from "./gesture";
import {
  type Draft,
  draftScreenPath,
  finishDraft,
  localScale,
  MAX_POINTS,
  PALETTE,
  startDraft,
  strokeLocalPath,
} from "./stroke";
import type { BoardSource } from "./sync";

export type ToolMode = "Pencil" | "Pan" | "Eraser";

export type Tool = { size: PencilSize; primary: number; secondary: number; mode: ToolMode };

type Entry = { tile: Tile; stroke: Stroke; path: Path2D };

const BLOCKED_TOUCH_EVENTS = [
  "touchstart",
  "touchmove",
  "gesturestart",
  "gesturechange",
  "gestureend",
] as const;

const ERASER_STEP_PX = 4;

const CURSOR_THROTTLE_MS = 50;

type RemoteCursor = { x: number; y: number; name: string; colour: string };

const remoteCursor = (clientId: number, state: unknown): RemoteCursor | undefined => {
  if (typeof state !== "object" || state === null) return undefined;
  const { cursor, user } = state as Record<string, unknown>;
  if (typeof cursor !== "object" || cursor === null) return undefined;
  const { x, y } = cursor as Record<string, unknown>;
  if (typeof x !== "number" || typeof y !== "number") return undefined;
  const name =
    typeof user === "object" &&
    user !== null &&
    typeof (user as { name?: unknown }).name === "string"
      ? (user as { name: string }).name
      : "Guest";
  return { x, y, name, colour: PALETTE[clientId % PALETTE.length] ?? PALETTE[0] };
};

const DEFAULT_CAMERA: Camera = { x: 0, y: 0, zoom: 1 };

const isCamera = (value: unknown): value is Camera => {
  if (typeof value !== "object" || value === null) return false;
  const { x, y, zoom } = value as Record<string, unknown>;
  return (
    typeof x === "number" &&
    typeof y === "number" &&
    typeof zoom === "number" &&
    Number.isFinite(x) &&
    Number.isFinite(y) &&
    zoom > 0 &&
    Number.isFinite(zoom)
  );
};

const cameraKey = (boardId: string): string => `stallion:camera:${boardId}`;

const loadCamera = (boardId: string): Camera => {
  try {
    const parsed: unknown = JSON.parse(localStorage.getItem(cameraKey(boardId)) ?? "null");
    return isCamera(parsed) ? parsed : DEFAULT_CAMERA;
  } catch {
    return DEFAULT_CAMERA;
  }
};

const saveCamera = (boardId: string, camera: Camera): void => {
  try {
    localStorage.setItem(cameraKey(boardId), JSON.stringify(camera));
  } catch {
    // Camera position is a per-viewer convenience; losing it only recentres the board.
  }
};

export type Surface = { dispose(): void };

export function createSurface(
  canvas: HTMLCanvasElement,
  boardId: string,
  source: BoardSource,
  currentTool: () => Tool,
): Surface {
  const context = canvas.getContext("2d");
  if (!context) throw new Error("This browser cannot create a 2D canvas context.");
  const ctx = context;

  const entries = new Map<string, Entry>();
  let ordered: Entry[] = [];
  let camera = loadCamera(boardId);
  let draft: Draft | undefined;
  let eraser: Point | undefined;
  let spaceDown = false;
  let frame = 0;
  let settleTimer: ReturnType<typeof setTimeout> | undefined;
  let cursors: RemoteCursor[] = [];
  let cursorSentAt = 0;
  const gestures = createGestures();
  const awareness = source.awareness;

  const size = () => ({ width: canvas.clientWidth, height: canvas.clientHeight });

  const render = () => {
    frame = 0;
    const dpr = window.devicePixelRatio || 1;
    const { width, height } = size();
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const view = viewBounds(camera, width, height);
    for (const entry of ordered) {
      if (!isVisible(entry.stroke.bbox, view, camera.zoom)) continue;
      const origin = tileBounds(entry.tile);
      const scale = localScale(entry.tile) * camera.zoom * dpr;
      ctx.setTransform(
        scale,
        0,
        0,
        scale,
        (origin.minX - camera.x) * camera.zoom * dpr,
        (origin.minY - camera.y) * camera.zoom * dpr,
      );
      ctx.fillStyle = PALETTE[entry.stroke.colour] ?? PALETTE[0];
      ctx.fill(entry.path);
    }
    if (draft && draft.points.length > 0) {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.fillStyle = PALETTE[draft.colour] ?? PALETTE[0];
      ctx.fill(draftScreenPath(draft, (world) => worldToScreen(camera, world), camera.zoom));
    }
    if (cursors.length > 0) renderCursors(dpr);
  };

  const renderCursors = (dpr: number) => {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.font = "12px system-ui, sans-serif";
    ctx.textBaseline = "middle";
    for (const cursor of cursors) {
      const { x, y } = worldToScreen(camera, cursor);
      ctx.fillStyle = cursor.colour;
      ctx.beginPath();
      ctx.arc(x, y, 5, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillText(cursor.name, x + 9, y);
    }
  };

  const requestRender = () => {
    if (frame === 0) frame = requestAnimationFrame(render);
  };

  const resize = () => {
    const dpr = window.devicePixelRatio || 1;
    const { width, height } = size();
    canvas.width = Math.round(width * dpr);
    canvas.height = Math.round(height * dpr);
    render();
  };

  const add = ({ tile, object }: StoredObject) => {
    if (object.type !== "Stroke") return;
    const entry = { tile, stroke: object, path: strokeLocalPath(tile, object) };
    const previous = entries.get(object.objectId);
    entries.set(object.objectId, entry);
    const rest = previous ? ordered.filter((other) => other !== previous) : ordered;
    const index = rest.findIndex((other) => other.stroke.objectId > object.objectId);
    ordered =
      index === -1 ? [...rest, entry] : [...rest.slice(0, index), entry, ...rest.slice(index)];
  };

  const eraseAt = (screen: Point) => {
    const { width, height } = size();
    const view = viewBounds(camera, width, height);
    const world = screenToWorld(camera, screen);
    for (const entry of ordered) {
      if (!isVisible(entry.stroke.bbox, view, camera.zoom)) continue;
      if (hitsStroke(entry.tile, entry.stroke, world, camera.zoom))
        source.erase(entry.stroke.objectId);
    }
  };

  const eraseTo = (screen: Point) => {
    const from = eraser ?? screen;
    const steps = Math.max(
      1,
      Math.ceil(Math.hypot(screen.x - from.x, screen.y - from.y) / ERASER_STEP_PX),
    );
    for (let step = 1; step <= steps; step++) {
      const t = step / steps;
      eraseAt({ x: from.x + (screen.x - from.x) * t, y: from.y + (screen.y - from.y) * t });
    }
    eraser = screen;
  };

  const discard = (objectId: string) => {
    const entry = entries.get(objectId);
    if (!entry) return;
    entries.delete(objectId);
    ordered = ordered.filter((other) => other !== entry);
  };

  const onObjects = (changed: ReadonlySet<string>) => {
    for (const objectId of changed) {
      const stored = source.objects.get(objectId);
      if (stored) add(stored);
      else discard(objectId);
    }
    requestRender();
  };

  const onAwareness = () => {
    if (!awareness) return;
    cursors = [...awareness.getStates()].flatMap(([clientId, state]) => {
      if (clientId === awareness.clientID) return [];
      const cursor = remoteCursor(clientId, state);
      return cursor ? [cursor] : [];
    });
    requestRender();
  };

  const shareCursor = (screen: Point | undefined) => {
    if (!awareness) return;
    if (!screen) {
      awareness.setLocalStateField("cursor", null);
      return;
    }
    const now = performance.now();
    if (now - cursorSentAt < CURSOR_THROTTLE_MS) return;
    cursorSentAt = now;
    awareness.setLocalStateField("cursor", screenToWorld(camera, screen));
  };

  const updateView = () => {
    const { width, height } = size();
    source.view(viewBounds(camera, width, height), camera.zoom);
  };

  const settle = () => {
    clearTimeout(settleTimer);
    settleTimer = setTimeout(() => saveCamera(boardId, camera), 150);
    updateView();
  };

  const moveCamera = (next: Camera) => {
    if (!isCamera(next)) return;
    camera = next;
    requestRender();
    settle();
  };

  const commit = () => {
    if (!draft) return;
    const stored = finishDraft(draft);
    draft = undefined;
    if (!stored) return;
    source.commit(stored);
  };

  const localPoint = (event: PointerEvent | WheelEvent): Point => {
    const rect = canvas.getBoundingClientRect();
    return { x: event.clientX - rect.left, y: event.clientY - rect.top };
  };

  const addPoint = (event: PointerEvent) => {
    if (!draft) return;
    const world = screenToWorld(camera, localPoint(event));
    const pressure = event.pointerType === "pen" ? Math.min(1, Math.max(0, event.pressure)) : 0.5;
    if (draft.points.length >= MAX_POINTS) {
      const last = draft.points.at(-1);
      const next: Draft = { ...draft, points: last ? [last] : [] };
      commit();
      draft = next;
    }
    draft.points.push([world.x, world.y, pressure]);
  };

  const pointerKind = (event: PointerEvent): PointerKind =>
    event.pointerType === "pen" || event.pointerType === "touch" ? event.pointerType : "mouse";

  const apply = (effects: readonly Effect[], event: PointerEvent) => {
    for (const effect of effects) {
      switch (effect.type) {
        case "StartStroke": {
          const tool = currentTool();
          if (tool.mode === "Eraser") {
            eraser = undefined;
            eraseTo(localPoint(event));
            break;
          }
          draft = startDraft(
            effect.secondary ? tool.secondary : tool.primary,
            tool.size,
            camera.zoom,
          );
          addPoint(event);
          break;
        }
        case "ExtendStroke": {
          const samples = event.getCoalescedEvents?.() ?? [];
          for (const sample of samples.length > 0 ? samples : [event]) {
            if (eraser) eraseTo(localPoint(sample));
            else addPoint(sample);
          }
          break;
        }
        case "CommitStroke":
          eraser = undefined;
          commit();
          break;
        case "DiscardStroke":
          eraser = undefined;
          draft = undefined;
          break;
        case "Pan":
          moveCamera(pan(camera, effect.dx, effect.dy));
          break;
        case "Pinch":
          moveCamera(pinch(camera, effect.from, effect.to));
          break;
      }
    }
    if (effects.length > 0) requestRender();
  };

  const onPointerDown = (event: PointerEvent) => {
    event.preventDefault();
    canvas.setPointerCapture(event.pointerId);
    const effects = gestures.down(
      {
        pointerId: event.pointerId,
        kind: pointerKind(event),
        button: event.button,
        point: localPoint(event),
      },
      { panTool: currentTool().mode === "Pan", spaceDown },
    );
    apply(effects, event);
  };

  const onPointerMove = (event: PointerEvent) => {
    shareCursor(localPoint(event));
    apply(gestures.move(event.pointerId, localPoint(event)), event);
  };

  const onPointerUp = (event: PointerEvent) => {
    apply(gestures.up(event.pointerId), event);
  };

  const onPointerCancel = (event: PointerEvent) => {
    apply(gestures.cancel(event.pointerId), event);
  };

  const onWheel = (event: WheelEvent) => {
    event.preventDefault();
    const factor = wheelFactor(event.ctrlKey ? event.deltaY * 3 : event.deltaY, event.deltaMode);
    moveCamera(zoomAt(camera, localPoint(event), factor));
  };

  const onKey = (event: KeyboardEvent) => {
    if (event.code !== "Space") return;
    event.preventDefault();
    spaceDown = event.type === "keydown";
  };

  const onPointerLeave = () => shareCursor(undefined);

  const preventDefault = (event: Event) => event.preventDefault();

  const unobserve = source.objects.observe(onObjects);
  awareness?.on("change", onAwareness);

  const observer = new ResizeObserver(() => {
    resize();
    settle();
  });
  observer.observe(canvas);

  canvas.addEventListener("pointerdown", onPointerDown);
  canvas.addEventListener("pointermove", onPointerMove);
  canvas.addEventListener("pointerup", onPointerUp);
  canvas.addEventListener("pointercancel", onPointerCancel);
  canvas.addEventListener("pointerleave", onPointerLeave);
  canvas.addEventListener("wheel", onWheel, { passive: false });
  canvas.addEventListener("contextmenu", preventDefault);
  for (const type of BLOCKED_TOUCH_EVENTS) {
    canvas.addEventListener(type, preventDefault, { passive: false });
  }
  window.addEventListener("keydown", onKey);
  window.addEventListener("keyup", onKey);

  resize();
  onObjects(new Set(source.objects.keys()));
  onAwareness();
  updateView();

  return {
    dispose() {
      clearTimeout(settleTimer);
      cancelAnimationFrame(frame);
      observer.disconnect();
      canvas.removeEventListener("pointerdown", onPointerDown);
      canvas.removeEventListener("pointermove", onPointerMove);
      canvas.removeEventListener("pointerup", onPointerUp);
      canvas.removeEventListener("pointercancel", onPointerCancel);
      canvas.removeEventListener("pointerleave", onPointerLeave);
      canvas.removeEventListener("wheel", onWheel);
      canvas.removeEventListener("contextmenu", preventDefault);
      for (const type of BLOCKED_TOUCH_EVENTS) canvas.removeEventListener(type, preventDefault);
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("keyup", onKey);
      unobserve();
      awareness?.off("change", onAwareness);
      saveCamera(boardId, camera);
    },
  };
}

